enum class Color { Red, Green, Blue };   // Scoped enum
enum Alert { Green, Yellow, Red };     // Unscoped enum

void run_checks() {
  Color c = Color::Red; // Must be qualified
  Alert a = Red;        // Unscoped enumerator is in the global scope (potential clash)

  // if (c == a) {}      // Compile Error: No implicit conversion between different enum types
  // int c_val = c;     // Compile Error: No implicit conversion to int
  int a_val = a;        // OK: Unscoped enum implicitly converts to int

  int c_val_explicit = static_cast<int>(c); // OK: Explicit cast is required
}
